use dlm_transport_proof::*;
fn policy()->Policy{Policy{delivery:1,latency:1000,loss:1,throughput:1,cost:1,max_age:1000,min_samples:2,min_hold:100,hysteresis:10}}
fn observations()->[Observation;6]{std::array::from_fn(|i|Observation{id:i as u64+1,at:100,rtt:1000,goodput:1000000,samples:4,loss:0,profile:i as u32+1,properties:properties(i as u32+1,1),cost:i as u32,ready:true})}
fn put32(out:&mut Vec<u8>,n:u32){out.extend(n.to_be_bytes());}fn put64(out:&mut Vec<u8>,n:u64){out.extend(n.to_be_bytes());}
fn certificate(r:Requirements,p:Policy,values:[Observation;6],now:u64)->Vec<u8>{let choice=select(r,p,&values,now);let mut out=b"DOT1".to_vec();for n in[r.required,r.forbidden,r.preferred,p.delivery,p.latency,p.loss,p.throughput,p.cost,p.max_age,p.min_samples,p.min_hold,p.hysteresis]{put32(&mut out,n);}put64(&mut out,now);put32(&mut out,6);put64(&mut out,choice.id);put64(&mut out,choice.score);for n in[choice.profile,choice.properties,choice.index,choice.status]{put32(&mut out,n);}for o in values{for n in[o.id,o.at,o.rtt,o.goodput,o.samples]{put64(&mut out,n);}for n in[o.loss,o.profile,o.properties,o.cost,o.ready as u32]{put32(&mut out,n);}}out}
#[test]fn mandatory_properties_always_precede_ranking(){let p=policy();let values=observations();for required in 0..512{for forbidden in[0,1,2,4,8,16,32,64,128,256,511]{let r=Requirements{required,forbidden,preferred:0};let chosen=select(r,p,&values,100);if chosen.status==0{assert_eq!(chosen.properties&required,required);assert_eq!(chosen.properties&forbidden,0);assert_eq!(chosen.properties,properties(chosen.profile,p.delivery));}}}}
#[test]fn only_fresh_real_profile_observations_are_eligible(){let p=policy();let r=Requirements{required:8,..Default::default()};let mut values=observations();values[3].cost=1000000;assert_eq!(select(r,p,&values,100).profile,5);for o in &mut values{o.properties=511;}assert_eq!(select(r,p,&values,100).status,6);let values=observations();assert_eq!(select(r,p,&values,1101).status,6);assert_eq!(select(r,p,&values,99).status,6);assert_eq!(select(Requirements{required:256,..Default::default()},p,&values,100).status,6);}
#[test]fn arithmetic_limits_and_invalid_policies_never_wrap(){let p=Policy{latency:1000000,loss:1000000,throughput:1000000,cost:1000000,..policy()};let o=Observation{rtt:60000000000,loss:1000000,cost:1000000,..observations()[0]};assert!(score(o,p)<u64::MAX/100);let invalid=Observation{rtt:u64::MAX,goodput:u64::MAX,loss:u32::MAX,cost:u32::MAX,..o};assert_eq!(score(invalid,p),u64::MAX);assert_eq!(select(Requirements::default(),Policy{latency:u32::MAX,..p},&observations(),u64::MAX).status,4);}
#[test]fn selected_score_profile_and_property_mask_cannot_be_forged(){let input=certificate(Requirements{required:4,..Default::default()},policy(),observations(),100);assert_eq!(input.len(),456);let valid=check_selection(&input,6).unwrap();assert!(valid.json().contains("\"native_pending\":true"));for i in 64..96{let mut bad=input.clone();bad[i]^=1;assert!(check_selection(&bad,6).is_err(),"claim byte {i}");}let mut bad=input.clone();bad[155]=2;assert!(check_selection(&bad,6).is_err());assert_eq!(check_selection(&input,5).unwrap_err(),Error::UnknownWithinBudget);}
#[test]fn hostile_certificate_lengths_and_bits_are_bounded(){let mut seed=144u64;for n in 0..1025{let bytes=(0..n).map(|_|{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1);(seed>>32)as u8}).collect::<Vec<_>>();assert!(check_selection(&bytes,100).is_err());assert!(check_migration_certificate(&bytes,100).is_err());}}
#[test]fn migration_model_preserves_wal_and_dedup_in_both_delivery_modes(){for messages in 1..=4{for window in 1..=messages{for delivery in[1,2]{let a=check_migration(messages,window,delivery,1000000).unwrap();let b=check_migration(messages,window,delivery,1000000).unwrap();assert_eq!((a.states,a.transitions),(b.states,b.transitions));assert!(a.states>10 && a.work<=1000000);}}}assert_eq!(check_migration(4,4,1,1).unwrap_err(),Error::UnknownWithinBudget);assert!(check_migration(5,4,1,1000000).is_err());}
#[test]fn migration_certificate_must_match_independent_exploration(){let r=check_migration(4,4,2,1000000).unwrap();let mut bytes=b"DML1".to_vec();for n in[4,4,2]{put32(&mut bytes,n);}put64(&mut bytes,r.states as u64);put64(&mut bytes,r.transitions as u64);put32(&mut bytes,31);assert!(check_migration_certificate(&bytes,1000000).is_ok());bytes[35]=255;assert!(check_migration_certificate(&bytes,1000000).is_err());}
